                return 0.0  # Stop cooling
            else:
                return -0.8  # Moderate cooling
        else:
            # Otherwise, cool aggressively but safely
            if sigma < max_safe_sigma:
                return -1.0  # Full cooling
            else:
                # If sigma is approaching or above safe level, reduce cooling
                return -0.5
    else:
        # No probe data yet — use conservative policy to start
        # We aim to cool quickly but avoid overshoot and shower
        if T <= T_target + 0.25:
            return 0.0  # Stop cooling if near target
        else:
            return -0.8  # Moderate cooling to stay safe

    # Safety fallback: if we're far from target and above threshold, cool aggressively
    if T > T_target + 0.5:
        return -1.0
    else:
        return 0.0
